    },
    {
      "name": "County Issue",
      "description": "a matter relevant to the county which is to be resolved"
    },
    {
      "name": "Scheduled Meeting",
      "description": "all stakeholders come together to address an issue",
      "attributes": "Meeting Time"
    },
    {
      "name": "Meeting Time",
      "description": "the specific time/date that the meeting is held"
    },
    {
      "name": "Stakeholder",
      "description": "a party that is relevant to an issue"
    },
    {
      "name": "Plan Review Meeting",
      "description": "held between the applicant and the plan review staff"
    },
    {
      "name": "Hearing",
      "description": "a meeting where a board decides on an application",
      "attributes": "Hearing Date, Governing Body, Hearing Decision, Affidavit"
    },
    {
      "name": "Hearing Date",
      "description": "the date of the hearing"
    },
    {
      "name": "Governing Body",
      "description": "the body responsible for the issue"
    },
    {
      "name": "Affidavit",
      "description": "a sworn statement of fact, required as proof that certain requirements are met"
    },
    {
      "name": "Hearing Decision",
      "description": "whether an application is to be approved or not"
    },
    {
      "name": "County Rules",
