    },
    {
      "name": "Comprehensive Plan",
      "description": "policy document that contains the documentation of the development of the county"
    },
    {
      "name": "Plan Report",
      "description": "a document containing all the relevant information of a plan"
    },
    {
      "name": "Zoning Information",
      "description": "relevant data about zoning"
    },
    {
      "name": "Violation Notice",
      "description": "issued when a violation against county policies is noticed by an enforcer"
    },
    {
      "name": "GIS (Geographic Information System)",
      "description": "the County's computer system for capturing, storing, and displaying data related to geographic positions (for technical members)"
    },
    {
      "name": "Geospatial Data",
      "description": "relevant to reviews"
    },
    {
      "name": "Parcel",
      "description": "a unit of land or real estate",
      "attributes": "Parcel Pin, Property History"
    },
    {
      "name": "Property History",
      "description": "contains all relevant past information to the property"
    },
    {
      "name": "ParcelPIN",
      "description": "A unique number assigned to a parcel for tracking and record-keeping"
    },
    {
      "name": "Citation-Post",
      "description": "Information in form of a notice of violation to be sent to the affected property owner"
    },
    {
      "name": "Project",
      "description": "an endeavor by a resident for construction or such",
      "attributes": "County Service, Bond, Plan Set, Building Development Status"
    }
  ]
